// Logged-in dashboard only. Counts down to the start of the exam DATE in IST,
// because an official exam reporting time has not been verified.
const SUPER100_LEVEL1_DATE_START=Date.parse('2026-12-16T00:00:00+05:30');
let examCountdownTimer=null;
function startExamCountdown(){
 if(examCountdownTimer!==null){clearInterval(examCountdownTimer);examCountdownTimer=null;}
 const container=document.getElementById('s100-countdown');
 if(!container || !user || !profile?.approved)return;
 function tick(){
  if(!container.isConnected || !user){clearInterval(examCountdownTimer);examCountdownTimer=null;return;}
  const diff=Math.max(0,SUPER100_LEVEL1_DATE_START-Date.now());
  const total=Math.floor(diff/1000);
  const vals=[Math.floor(total/86400),Math.floor((total%86400)/3600),Math.floor((total%3600)/60),total%60];
  ['days','hours','minutes','seconds'].forEach((name,index)=>{
   const node=container.querySelector('[data-part="'+name+'"]');
   if(node)node.textContent=String(vals[index]).padStart(index?2:1,'0');
  });
  const status=container.querySelector('.exam-countdown-status');
  if(status)status.textContent=diff===0?'Exam date has arrived / परीक्षा की तारीख आ गई है':'Counting down to 16 December 2026 (00:00 IST date boundary) / 16 दिसंबर की शुरुआत तक';
  if(!diff){clearInterval(examCountdownTimer);examCountdownTimer=null;}
 }
 tick();
 if(SUPER100_LEVEL1_DATE_START>Date.now())examCountdownTimer=setInterval(tick,1000);
}
async function home(){const p=await req(db.from('progress').select('*').eq('student',user.id));const done=topics.filter((_,i)=>p.some(x=>x.topic===i+1&&x.done)).length;const pct=Math.round(done/14*100);const [ar,tr]=await Promise.all([db.from('attempts').select('*').eq('student',user.id),db.from('tests').select('*').eq('published',true)]);const finished=(ar.data||[]).filter(x=>x.finished).sort((a,b)=>Date.parse(a.finished)-Date.parse(b.finished));const upcoming=(tr.data||[]).filter(t=>t.opens&&Date.parse(t.opens)>Date.now()).sort((a,b)=>Date.parse(a.opens)-Date.parse(b.opens));const recent=finished.slice(-7);shell(`<div class="m3-toprow"><div class="dashhero"><div><small>THE SUPER 100 MISSION • CLASS OF 2027–29</small><h1>Welcome back,<br>${esc(displayUsername())}.</h1><p>Every chapter is a step closer to your goal. Your preparation, your progress, your future.</p><div class="m3-hero-actions"><button onclick="run(()=>chapter(${topics.findIndex((_,i)=>!p.some(x=>x.topic===i+1&&x.done))+1||1}))()">Continue learning</button><button class="m3-priority-cta" onclick="run(showPriorityHub)()">🔥 Priority Topics ↗</button></div></div><div class="heroart" aria-hidden="true">∑<span>π &nbsp; √x</span></div></div><section class="exam-countdown" id="s100-countdown" aria-label="Super 100 entrance exam date countdown"><div class="exam-countdown-top"><div><small>SUPER 100 • LEVEL 1 • SESSION 2027–29</small><h2>Exam Countdown / परीक्षा काउंटडाउन</h2><p>Exam date: 16 December 2026 / परीक्षा तिथि: 16 दिसंबर 2026</p></div><span class="exam-date-chip">16 DEC 2026</span></div><div class="exam-countdown-grid"><div><strong data-part="days">–</strong><span>Days / दिन</span></div><div><strong data-part="hours">–</strong><span>Hours / घंटे</span></div><div><strong data-part="minutes">–</strong><span>Minutes / मिनट</span></div><div><strong data-part="seconds">–</strong><span>Seconds / सेकंड</span></div></div><p class="exam-countdown-status">Loading countdown...</p><p class="exam-countdown-disclaimer">Exam start time has not been verified. This timer reaches zero at the beginning of the exam date (12:00 AM IST), NOT at the exam reporting/start time. / परीक्षा शुरू होने का समय अभी सत्यापित नहीं है।</p></section></div><div class="dashgrid"><section class="panel"><small>PERFORMANCE</small><h2>Recent test scores</h2>${ar.error?'<p>Scores unavailable.</p>':recent.length?`<div class="scorechart">${recent.map(x=>`<div><small>${esc(x.score)}/${esc(x.total)}</small><div class="bartrack"><i style="height:${Math.max(0,Math.min(100,x.total?100*x.score/x.total:0))}%"></i></div><small>#${esc(x.test_id)}</small></div>`).join('')}</div>`:'<p>Complete a test to see your performance here.</p>'}<button onclick="run(history)()">View results</button></section><section class="panel"><small>MISSION PROGRESS</small><div class="ring" style="--pct:${pct}%"><strong>${pct}%</strong></div><h3>${done}/14 chapters completed</h3><p>${ar.error?'Tests unavailable':finished.length+' tests completed'}</p></section><section class="panel schedule"><small>YOUR SCHEDULE</small><h2>Upcoming tests</h2>${tr.error?'<p>Schedule unavailable.</p>':upcoming.slice(0,4).map(t=>`<div class="scheduleitem"><b>${esc(t.title)}</b><small>${esc(new Date(t.opens).toLocaleString())}</small></div>`).join('')||'<p>No scheduled upcoming tests.</p>'}<button onclick="run(()=>tests(false))()">All tests</button><button onclick="run(()=>tests(true))()">PYQs</button></section></div><section class="m3-chapter-block"><div class="sectionhead"><div><span class="m3-heading-eyebrow">THE LEARNING PATH • 14 CHAPTERS</span><h2>Explore Mathematics / गणित</h2><small>Chapter notes, PDFs, formulas and exam-style practice at your fingertips.</small></div><small>2026 Level 1 syllabus · 2027 syllabus not confirmed</small></div><div class="grid m3-chapters">${topics.map((t,i)=>`<article><small>TOPIC ${String(i+1).padStart(2,'0')}</small><h3>${esc(t)}</h3><button onclick="run(()=>chapter(${i+1}))()">Open / खोलें</button><label><input type="checkbox" ${p.some(x=>x.topic===i+1&&x.done)?'checked':''} onchange="run(()=>mark(${i+1},this.checked))()"> Complete / पूरा</label></article>`).join('')}</div></section><details class="panel m3-scratchpad"><summary>📝 Personal Scratchpad / अपनी योजना</summary><h3>Study planner / योजना</h3><textarea id="plan" placeholder="Daily targets">${esc(localStorage.getItem('plan:'+user.id)||'')}</textarea><button onclick="localStorage.setItem('plan:'+user.id,val('plan'));alert('Saved on this browser')">Save</button></details>`);startExamCountdown();try{window.Modern2?.mount(p,finished)}catch(error){console.error("Study dashboard could not initialize:",error);const target=document.querySelector(".m3-toprow");if(target){const notice=document.createElement("div");notice.className="m3-widget-error";notice.textContent="Study tools temporarily unavailable. Notes, tests and chapter resources are still accessible.";target.after(notice)}}try{window.PriorityHub?.mount(p)}catch(error){console.error("Priority Hub initialization failed:",error)}}
