 q.map((x,j)=>'<details class="chapter-question"><summary><b>Q'+(j+1)+' · '+esc(x.difficulty.toUpperCase())+'</b> — '+esc(x.prompt)+'</summary><ol type="A">'+x.options.map(v=>'<li>'+esc(v)+'</li>').join('')+'</ol><div class="chapter-answer"><b>Correct answer / सही उत्तर: '+String.fromCharCode(65+x.answer)+'. '+esc(x.options[x.answer])+'</b><p>Solution / हल: '+esc(x.explanation)+'</p></div></details>').join('')+
 '<p class="chapter-source">Use the source paper for authentic question wording. Do not treat these practice MCQs as verified PYQs.</p></div>';
