async function chapter(k){const rows=await req(db.from('resources').select('*').eq('topic',k));const qs=await req(db.rpc('practice',{k}));shell(`<h1>${esc(topics[k-1])}</h1><button onclick="print()">Print notes / PDF</button><section class="panel"><h2>Revision / पुनरावृत्ति</h2><p>${esc(material[k-1][0])}</p><p>${esc(material[k-1][1])}</p><p>${esc(material[k-1][2])}</p><p>${esc(material[k-1][3])}</p><a target="_blank" rel="noopener" href="https://www.youtube.com/results?search_query=${encodeURIComponent(topics[k-1]+' maths aptitude Hindi lecture')}">Find lectures (search, not verified)</a></section><section class="panel"><h2>Extended concepts / विस्तृत अवधारणाएँ</h2><p>${esc(advancedNotes[k-1][0])}</p><p>${esc(advancedNotes[k-1][1])}</p><h3>Worked examples / हल उदाहरण</h3><ol>${advancedNotes[k-1][2].map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>Check units, restrictions and the base of each calculation. / इकाई, शर्त और गणना का आधार जाँचें।</p></section><section class="panel"><h2>Original practice / अभ्यास</h2><p>${esc(material[k-1][4])}</p>${material[k-1][5].map((o,j)=>`<button onclick="run(()=>localAnswer(${k},${j}))()">${esc(o)}</button>`).join('')}<p id="localfeedback"></p><button onclick="run(()=>saveItem(${k},'bookmark'))()">Bookmark</button></section>${['lecture','notes','formula','pyq','analysis'].map(kind=>`<section class="panel" id="chapter-section-${kind}"><h3>${kind.toUpperCase()}</h3>${kind==='notes'?`<div class="chapter-pdf-box"><p><strong>Chapter ${k}: ${esc(topics[k-1])}</strong></p><p>Hindi + English study notes / हिंदी और अंग्रेज़ी में अध्ययन सामग्री</p><div class="chapter-pdf-actions"><a href="pdf/${pdfNames[k-1]}" target="_blank" rel="noopener">📖 View PDF / PDF देखें</a><a href="pdf/${pdfNames[k-1]}" download>⬇ Download PDF / डाउनलोड करें</a><a href="notes.html#chapter-${k}" target="_blank" rel="noopener">Read online / ऑनलाइन पढ़ें</a></div><iframe class="chapter-pdf-frame" title="${esc(topics[k-1])} PDF notes" src="pdf/${pdfNames[k-1]}#toolbar=1" loading="lazy"></iframe></div>`:''}${chapterSupplement(kind,k)}${rows.filter(r=>r.kind===kind).map(r=>`<h4>${esc(r.title)}</h4>${kind==='lecture'&&/^https:\/\//.test(r.body)?`<a href="${esc(r.body)}" target="_blank" rel="noopener">Open lecture</a>`:`<pre>${esc(r.body)}</pre>`}`).join('')||((kind==='notes'||kind==='formula'||kind==='pyq'||kind==='analysis')?'':'<p>Awaiting admin content.</p>')}</section>`).join('')}<h2>Practice / अभ्यास</h2><p>Track daily practice and revise mistakes in the advanced practice workspace.</p><button onclick="run(()=>advancedPractice(${k}))()">Start practice (${qs.length} questions)</button>`)}
function scheduleStatus(t,now=Date.now()){return !t.published?'Draft':t.closes&&Date.parse(t.closes)<=now?'Closed':t.opens&&Date.parse(t.opens)>now?'Upcoming':'Open'}
function scheduleDate(v){return v?new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Kolkata'}).format(new Date(v))+' IST':'Not set'}
function scheduleISO(v){return v?new Date(v+':00+05:30').toISOString():null}
function scheduleValidate(o,c){if(o&&c&&Date.parse(c)<=Date.parse(o))throw Error('Closing time must be after opening time')}
function scheduleLocal(v){if(!v)return '';return new Date(Date.parse(v)+19800000).toISOString().slice(0,16)}
function scheduleCountdown(v){let s=Math.max(0,Math.ceil((Date.parse(v)-Date.now())/1000));return `${Math.floor(s/86400)}d ${Math.floor(s/3600)%24}h ${Math.floor(s/60)%60}m ${s%60}s`}
async function tests(pyq=false){const [ts,attempts]=await Promise.all([req(db.from('tests').select('*').eq('published',true)),req(db.from('attempts').select('test_id,finished').eq('student',user.id))]);const rows=ts.filter(t=>Boolean(t.is_pyq)===pyq);shell(`<h1>${pyq?'Previous year papers / पिछले प्रश्नपत्र':'Mock tests / परीक्षा'}</h1><p>All schedule times are IST. Access is checked by the server.</p><label>Filter <select id="schedulefilter"><option value="All">All</option><option>Upcoming</option><option>Open</option><option>Closed</option><option>Completed</option></select></label><div id="schedulecards"></div>`);const render=()=>{const node=el('schedulecards');if(!node)return;const filter=val('schedulefilter');node.innerHTML=rows.map(t=>{const state=scheduleStatus(t),attempt=attempts.find(a=>a.test_id===t.id),label=attempt?.finished?'Completed':state;if(filter!=='All'&&filter!==label)return '';return `<article><h3>${esc(t.title)}</h3><b>${label}</b><p>${t.minutes} minutes · Correct +${t.marks_correct??1} · Wrong ${t.marks_wrong??0}</p><p>Opens: ${scheduleDate(t.opens)} · Closes: ${scheduleDate(t.closes)}</p>${state==='Upcoming'?`<p>Starts in ${scheduleCountdown(t.opens)}</p>`:state==='Open'&&t.closes?`<p>Closes in ${scheduleCountdown(t.closes)}</p>`:''}<button ${state!=='Open'||attempt?.finished?'disabled':''} onclick="run(()=>start(${t.id}))()">${attempt?'Resume':'Start'}</button><button onclick="run(()=>board(${t.id}))()">Leaderboard</button></article>`}).join('')||'<p>No matching tests.</p>'};el('schedulefilter').onchange=render;render();timer=setInterval(render,1000)}
function scheduleAdmin(ts){return `<section class="panel"><h2>Test scheduling / परीक्षा समय</h2><p>IST (UTC+05:30). Only unpublished drafts can be rescheduled here. Publish separately to enable automatic availability.</p><div id="scheduleadmin">${ts.map(t=>`<article><b>#${t.id} ${esc(t.title)}</b> · ${scheduleStatus(t)}<p>${scheduleDate(t.opens)} — ${scheduleDate(t.closes)}</p>${!t.published?`<label>Opens IST <input type="datetime-local" id="so${t.id}" value="${scheduleLocal(t.opens)}"></label><label>Closes IST <input type="datetime-local" id="sc${t.id}" value="${scheduleLocal(t.closes)}"></label><button onclick="run(()=>saveSchedule(${t.id}))()">Save schedule</button>`:''}</article>`).join('')}</div></section>`}
async function saveSchedule(id){if(!profile.admin)throw Error('Admin only');const o=scheduleISO(val('so'+id)),c=scheduleISO(val('sc'+id));scheduleValidate(o,c);const rows=await req(db.from('tests').update({opens:o,closes:c}).eq('id',id).eq('published',false).select('id'));if(!rows.length)throw Error('Draft no longer editable');await admin()}
async function start(t){const meta=await req(db.from('tests').select('marks_correct,marks_wrong').eq('id',t).single());const d=await req(db.rpc('begin_test',{t}));shell(`<h2 id="clock"></h2><p>Maximum ${d.questions.length*meta.marks_correct} marks · Correct +${meta.marks_correct} · Wrong ${meta.marks_wrong} · Skipped 0</p><p id="answered"></p><form id="exam">${d.questions.map((q,i)=>`<article><h3>${i+1}. ${esc(q.prompt)}</h3>${q.options.map((o,j)=>`<label><input type="radio" name="${q.id}" value="${j}">${esc(o)}</label>`).join('')}<button type="button" onclick="this.parentElement.querySelectorAll('input').forEach(x=>x.checked=false);el('exam').onchange()">Clear answer</button></article>`).join('')}</form><button id="submit">Submit / जमा करें</button>`);const key='attempt:'+user.id+':'+t;const saved=JSON.parse(localStorage.getItem(key)||'{}');for(const input of el('exam').querySelectorAll('input'))input.checked=saved[input.name]===input.value;el('exam').onchange=()=>{const answers=Object.fromEntries(new FormData(el('exam')));localStorage.setItem(key,JSON.stringify(answers));el('answered').textContent=`Answered ${Object.keys(answers).length}/${d.questions.length}`};el('exam').onchange();let busy=false;const submit=async()=>{if(busy)return;busy=true;try{const r=await req(db.rpc('submit_test',{t,r:Object.fromEntries(new FormData(el('exam')))}));localStorage.removeItem(key);shell(`<h1>${r.score} / ${r.total} marks</h1><p>${r.total?(100*r.score/r.total).toFixed(1):0}%</p>${Number.isInteger(r.correct)?`<div class="grid"><article>Correct: ${r.correct}</article><article>Wrong: ${r.wrong}</article><article>Unattempted: ${r.unattempted}</article></div>`:''}<button onclick="run(()=>board(${t}))()">Leaderboard</button>`)}catch(e){busy=false;alert(e.message)}};bind('submit',submit);timer=setInterval(()=>{const s=Math.max(0,Math.ceil((Date.parse(d.deadline)-Date.now())/1000));el('clock').textContent=`${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`;if(!s){clearInterval(timer);submit()}},500)}
async function board(t){const r=await req(db.rpc('leaderboard',{t}));shell('<h1>Leaderboard / रैंकिंग</h1><table><tr><th>Rank</th><th>Username</th><th>Score</th></tr>'+r.map(x=>`<tr><td>${x.rank}</td><td>${esc(x.username)}</td><td>${x.score}/${x.total}</td></tr>`).join('')+'</table>')}
async function analytics(){
 const [attempts,stats]=await Promise.all([req(db.from('attempts').select('test_id,score,total,finished').eq('student',user.id)),req(db.rpc('mission_topic_analytics_v1'))]);
 const done=attempts.filter(a=>a.finished);const sum=done.reduce((n,a)=>n+Number(a.score||0),0),max=done.reduce((n,a)=>n+Number(a.total||0),0);
 const rows=stats.map(r=>{const c=Number(r.correct),w=Number(r.wrong),s=Number(r.skipped);return {...r,c,w,s,n:c+w,accuracy:c+w?Math.round(c/(c+w)*100):null}});
 const weak=rows.filter(r=>r.topic>=1&&r.topic<=14&&r.n>=5&&r.accuracy<60).sort((a,b)=>a.accuracy-b.accuracy);
 shell(`<h1>Performance analytics / प्रदर्शन विश्लेषण</h1><div class="grid"><article><h3>${done.length}</h3>Completed tests</article><article><h3>${sum}/${max}</h3>Total marks</article><article><h3>${max?(100*sum/max).toFixed(1)+'%':'—'}</h3>Overall marks percentage</article></div><section class="panel"><h2>Revision priorities / प्राथमिकताएँ</h2>${weak.length?weak.slice(0,3).map(r=>`<p>${esc(topics[r.topic-1])} · ${r.accuracy}% accuracy <button onclick="run(()=>chapter(${Number(r.topic)}))()">Revise</button></p>`).join(''):'<p>No weak topics identified with sufficient eligible attempts yet.</p>'}<p>Rule: below 60% accuracy after at least 5 answered questions.</p></section><section class="panel"><h2>Topic accuracy / विषयवार शुद्धता</h2><p>Correct ÷ answered. Skipped shown separately. Only completed tests whose scheduled closing time has passed are included, to protect ranked answers. Anytime tests are excluded from topic breakdown.</p>${rows.length?'<div style="overflow-x:auto"><table><tr><th>Topic</th><th>Correct</th><th>Wrong</th><th>Skipped</th><th>Accuracy</th></tr>'+rows.map(r=>`<tr><td>${esc(topics[r.topic-1]||'Other / '+r.topic)}</td><td>${r.c}</td><td>${r.w}</td><td>${r.s}</td><td>${r.accuracy===null?'—':r.accuracy+'%'}${r.n<5?' (limited data)':''}</td></tr>`).join('')+'</table></div>':'<p>No eligible closed-test data yet.</p>'}</section><button onclick="run(history)()">Score history</button>`);
}
async function history(){const r=await req(db.from('attempts').select('*').eq('student',user.id));shell(`<h1>My performance / प्रदर्शन</h1><section class="panel"><h3>Score history</h3>${r.filter(a=>a.finished).map(a=>`<p>Test #${a.test_id} · ${a.score}/${a.total}</p><progress max="100" value="${a.total?100*a.score/a.total:0}"></progress>`).join('') || 'No completed tests'}</section>`+r.map(x=>`<article>Test #${x.test_id} · ${x.finished?`${x.score}/${x.total}`:'In progress'} <button onclick="run(()=>review(${x.test_id}))()">Review</button></article>`).join(''))}
async function review(t){const r=await req(db.rpc('review_test',{t}));shell('<h1>Solutions / हल</h1>'+ (r.map(q=>`<article>${esc(q.prompt)}<p>Your answer: ${esc(q.options[q.selected])}</p><p>Correct: ${esc(q.options[q.answer])}</p>${esc(q.explanation)}</article>`).join('')||'<p>Solutions available after scheduled closing time. Anytime tests do not reveal ranked answers.</p>'))}
const topicSelect=()=>topics.map((t,i)=>`<option value="${i+1}">${esc(t)}</option>`).join('');
async function adminRows(table,columns){const out=[];for(let start=0;;start+=500){const batch=await req(db.from(table).select(columns).order(table==='progress'?'student':'id').order(table==='progress'?'topic':'id').range(start,start+499));out.push(...batch);if(batch.length<500)return out;}}
function adminOverview(users,attempts,progress,ts){const students=users.filter(u=>!u.admin),finished=attempts.filter(a=>a.finished&&students.some(u=>u.id===a.student)),pct=(n,d)=>d>0?(100*n/d).toFixed(1)+'%':'—';const rows=students.map(u=>{const a=finished.filter(x=>x.student===u.id),p=progress.filter(x=>x.student===u.id&&x.done).length;return {u,a,p,score:a.reduce((s,x)=>s+(x.score||0),0),total:a.reduce((s,x)=>s+(x.total||0),0)}});return `<section class="panel"><h2>Admin overview / छात्र विश्लेषण</h2><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px">${[['Students',students.length],['Approved',students.filter(u=>u.approved).length],['Pending / blocked',students.filter(u=>!u.approved).length],['Completed attempts',finished.length],['Published tests',ts.filter(t=>t.published).length],['Weighted score',pct(finished.reduce((s,a)=>s+(a.score||0),0),finished.reduce((s,a)=>s+(a.total||0),0))]].map(([k,v])=>`<article><small>${k}</small><h2>${v}</h2></article>`).join('')}</div><label>Search students <input id="adminsearch" placeholder="Username"></label><label>Status <select id="adminstatus"><option value="all">All</option><option value="approved">Approved</option><option value="pending">Pending / blocked</option></select></label><div style="overflow-x:auto"><table style="width:100%;text-align:left"><thead><tr><th>Student</th><th>Chapters</th><th>Tests</th><th>Marks</th><th>Score %</th><th>Status</th><th>Action</th></tr></thead><tbody id="adminrows">${rows.map(({u,a,p,score,total})=>`<tr data-name="${esc(u.username)}" data-status="${u.approved?'approved':'pending'}"><td><button onclick="run(()=>adminStudent('${u.id}'))()">${esc(u.username)}</button></td><td>${p}/14</td><td>${a.length}</td><td>${score}/${total}</td><td>${pct(score,total)}</td><td>${u.approved?'Approved':'Pending / blocked'}</td><td><button onclick="run(()=>approve('${u.id}',${!u.approved}))()">${u.approved?'Block':'Approve'}</button></td></tr>`).join('')}</tbody></table></div><button id="adminSummaryCsv">Export student summary CSV</button><h3>Test participation</h3>${ts.map(t=>{const n=finished.filter(a=>a.test_id===t.id).length;return `<p>${esc(t.title)} · ${n} completed · ${t.published?'Published':'Draft'}</p>`}).join('')}</section>`}
function adminSummaryBind(users,attempts,progress){const filter=()=>{const name=val('adminsearch').toLowerCase(),status=val('adminstatus');document.querySelectorAll('#adminrows tr').forEach(r=>r.hidden=!(r.dataset.name.toLowerCase().includes(name)&&(status==='all'||r.dataset.status===status)))};el('adminsearch').oninput=filter;el('adminstatus').onchange=filter;bind('adminSummaryCsv',()=>{const cell=v=>'"'+String(v??'').replace(/^[=+\-@\t\r]/,"'$&").replace(/"/g,'""')+'"';const lines=[['username','approved','chapters','completed_tests','score','maximum'],...users.filter(u=>!u.admin).map(u=>{const a=attempts.filter(x=>x.student===u.id&&x.finished);return [u.username,u.approved,progress.filter(x=>x.student===u.id&&x.done).length,a.length,a.reduce((s,x)=>s+(x.score||0),0),a.reduce((s,x)=>s+(x.total||0),0)]})];const url=URL.createObjectURL(new Blob(['\ufeff'+lines.map(r=>r.map(cell).join(',')).join('\n')],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='student-summary.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
async function adminStudent(id){if(!profile.admin)throw Error('Admin only');const u=await req(db.from('profiles').select('*').eq('id',id).single());const attempts=await adminRows('attempts','*'),progress=await req(db.from('progress').select('*').eq('student',id)),ts=await adminRows('tests','*');const a=attempts.filter(x=>x.student===id&&x.finished),testids=[...new Set(a.map(x=>x.test_id))],stats=topics.map(()=>({c:0,w:0,s:0}));for(const tid of testids){const qs=await req(db.from('questions').select('id,topic,answer').eq('test_id',tid));const attempt=a.find(x=>x.test_id===tid);for(const q of qs){const s=stats[q.topic-1];if(!s)continue;const v=attempt.responses?.[q.id];if(v==null||!['0','1','2','3'].includes(String(v)))s.s++;else if(String(v)===String(q.answer))s.c++;else s.w++}}shell(`<button onclick="run(admin)()">← Admin overview</button><h1>${esc(u.username)} — Student report</h1><p>${a.length} completed tests · ${progress.filter(x=>x.done).length}/14 chapters</p><section class="panel"><h2>Topic accuracy (ranked tests and PYQs)</h2><p>Weak = fewer than 60% correct with at least 5 answered. Browser-only practice is not included.</p><div style="overflow-x:auto"><table><thead><tr><th>Topic</th><th>Correct</th><th>Wrong</th><th>Skipped</th><th>Accuracy</th><th>Status</th></tr></thead><tbody>${stats.map((s,i)=>{const n=s.c+s.w,p=n?100*s.c/n:0;return `<tr><td>${esc(topics[i])}</td><td>${s.c}</td><td>${s.w}</td><td>${s.s}</td><td>${n?p.toFixed(1)+'%':'—'}</td><td>${n<5?'Insufficient data':p<60?'Weak':'On track'}</td></tr>`}).join('')}</tbody></table></div></section><section class="panel"><h2>Test history</h2>${a.map(x=>`<p>${esc(ts.find(t=>t.id===x.test_id)?.title||'Test '+x.test_id)} · ${x.score}/${x.total}</p>`).join('')||'<p>No completed tests</p>'}</section>`)}
async function admin(){if(!profile.admin)throw Error('Admin only');const [users,attempts,progress,ts]=await Promise.all([adminRows('profiles','*'),adminRows('attempts','id,student,test_id,finished,score,total'),adminRows('progress','*'),adminRows('tests','*')]);shell(`<h1>Admin control / प्रबंधन</h1>${adminOverview(users,attempts,progress,ts)}${scheduleAdmin(ts)}<h2>Students</h2>${users.map(u=>`<article><b>${esc(u.username)}</b> · ${u.approved?'Approved':'Pending/blocked'} · ${progress.filter(p=>p.student===u.id&&p.done).length}/14 chapters ${u.admin?'Admin':`<button onclick="run(()=>approve('${u.id}',${!u.approved}))()">${u.approved?'Block':'Approve'}</button>`}<p>${attempts.filter(a=>a.student===u.id).map(a=>`Test ${a.test_id}: ${a.score??'Pending'}/${a.total??'?'}`).join(' | ')}</p></article>`).join('')}<button id="csv">Export results CSV</button><section class="panel"><h2>Add learning resource</h2><select id="rt">${topicSelect()}</select><select id="rk">${['lecture','notes','formula','pyq','analysis'].map(k=>`<option>${k}</option>`)}</select><input id="rtitle" placeholder="Title"><textarea id="body" placeholder="Text or HTTPS lecture URL"></textarea><button id="resource">Add</button></section><section class="panel"><h2>Create test</h2><input id="tt" placeholder="Bilingual title"><input id="mins" type="number" value="30" min="1"><label><input id="pyqflag" type="checkbox">Previous year paper</label><label>Marks per correct<input id="mc" type="number" value="1" min="1" step="1"></label><label>Marks per wrong<input id="mw" type="number" value="0" max="0" step="1"></label><button id="pyqpreset">Use +4 / −1 preset</button><label>Opens IST (optional)<input id="opens" type="datetime-local"></label><label>Closes IST (optional)<input id="closes" type="datetime-local"></label><button id="create">Create draft</button>${ts.map(t=>`<p>#${t.id} ${esc(t.title)} ${t.published?'Published':`<button onclick="run(()=>publish(${t.id}))()">Publish</button>`}</p>`).join('')}</section><section class="panel"><h2>Add question</h2><select id="qt">${topicSelect()}</select><select id="testid"><option value="">Practice bank</option>${ts.filter(t=>!t.published).map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select><textarea id="prompt" placeholder="Question / प्रश्न"></textarea>${[0,1,2,3].map(i=>`<input id="o${i}" placeholder="Option ${i+1}">`).join('')}<select id="ans">${[0,1,2,3].map(i=>`<option value="${i}">Correct option ${i+1}</option>`).join('')}</select><textarea id="exp" placeholder="Explanation / हल"></textarea><button id="addq">Add question</button></section><section class="panel"><h2>Bulk question upload (JSON)</h2><p>Uses selected topic and draft test above. Array of objects: prompt, options (four strings), answer (0–3), explanation.</p><input id="bulkfile" type="file" accept=".json,application/json"><textarea id="bulk" placeholder="Paste JSON array"></textarea><button id="bulkadd">Import questions</button></section><section class="panel"><h2>Announcements</h2><input id="noticeTitle" placeholder="Title"><textarea id="noticeBody" placeholder="Message"></textarea><button id="noticeAdd">Publish announcement</button></section>`);adminSummaryBind(users,attempts,progress);bind('resource',async()=>{await req(db.from('resources').insert({topic:+val('rt'),kind:val('rk'),title:val('rtitle'),body:val('body')}));alert('Added')});bind('pyqpreset',()=>{el('mc').value=4;el('mw').value=-1;el('mins').value=120;el('pyqflag').checked=true});bind('create',async()=>{if(!val('tt').trim()||!Number.isInteger(+val('mins'))||+val('mins')<1||!val('mc')||!Number.isInteger(+val('mc'))||+val('mc')<1||!val('mw')||!Number.isInteger(+val('mw'))||+val('mw')>0)throw Error('Invalid title, duration or marking');scheduleValidate(scheduleISO(val('opens')),scheduleISO(val('closes')));await req(db.from('tests').insert({title:val('tt'),minutes:+val('mins'),marks_correct:+val('mc'),marks_wrong:+val('mw'),is_pyq:el('pyqflag').checked,opens:scheduleISO(val('opens')),closes:scheduleISO(val('closes'))}));admin()});bind('addq',async()=>{await req(db.from('questions').insert({topic:+val('qt'),test_id:val('testid')?+val('testid'):null,prompt:val('prompt'),options:[0,1,2,3].map(i=>val('o'+i)),answer:+val('ans'),explanation:val('exp')}));alert('Added')});bind('bulkadd',async()=>{const file=el('bulkfile').files[0];const rows=JSON.parse(file?await file.text():val('bulk'));if(!Array.isArray(rows)||!rows.length||rows.length>500||rows.some(q=>typeof q.prompt!=='string'||!q.prompt.trim()||!Array.isArray(q.options)||q.options.length!==4||q.options.some(o=>typeof o!=='string'||!o.trim())||!Number.isInteger(q.answer)||q.answer<0||q.answer>3))throw Error('Invalid JSON questions (1–500)');await req(db.from('questions').insert(rows.map(q=>({topic:+val('qt'),test_id:val('testid')?+val('testid'):null,prompt:q.prompt,options:q.options,answer:q.answer,explanation:String(q.explanation||'')}))));alert('Imported '+rows.length)});bind('noticeAdd',async()=>{await req(db.from('resources').insert({topic:0,kind:'announcement',title:val('noticeTitle'),body:val('noticeBody')}));alert('Published')});bind('csv',()=>{const lines=['student_id,test_id,score,total',...attempts.map(a=>[a.student,a.test_id,a.score,a.total].join(','))];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/csv'}));a.download='results.csv';a.click();URL.revokeObjectURL(a.href)});try{window.Admin3?.mount({users,attempts,progress,ts})}catch(error){console.error("Admin visual enhancement failed:",error)}}
async function approve(id,approved){if(!profile?.admin||!profile.approved)throw Error('Admin only');if(!confirm(approved?'Approve this student?':'Block this student?'))return;const updated=await req(db.from('profiles').update({approved}).eq('id',id).eq('admin',false).select('id,approved').single());if(updated.approved!==approved)throw Error('Approval update failed');await admin()}async function publish(id){const q=await req(db.from('questions').select('id').eq('test_id',id));if(!q.length)throw Error('Add questions first');await req(db.from('tests').update({published:true}).eq('id',id));admin()}

async function saveItem(k,kind){await req(db.from('study_items').upsert({student:user.id,topic:k,kind}));alert('Saved')}
async function localAnswer(k,j){const m=material[k-1];el('localfeedback').textContent=(j===m[6]?'Correct / सही: ':'Incorrect / गलत: ')+m[7];if(j!==m[6])await req(db.from('study_items').upsert({student:user.id,topic:k,kind:'mistake'}))}
function plannerTasks(progress,stats,minutes,day){
 const rows=new Map(stats.map(r=>[Number(r.topic),r]));
 const ranked=topics.map((_,i)=>{const topic=i+1,r=rows.get(topic),n=Number(r?.correct||0)+Number(r?.wrong||0),accuracy=n?100*Number(r.correct)/n:null,done=progress.some(p=>Number(p.topic)===topic&&p.done);return {topic,accuracy,priority:n>=5&&accuracy<60?0:!done?1:n>=5&&accuracy>=80?3:2}}).sort((a,b)=>a.priority-b.priority||(a.priority===0?a.accuracy-b.accuracy:0)||a.topic-b.topic);
 const best=ranked.filter(r=>r.priority===ranked[0].priority);const rotation=Number(day.replaceAll('-',''))%best.length;const a=best[rotation];const others=ranked.filter(r=>r.topic!==a.topic);const rev=others.filter(r=>r.priority>=2);const b=(rev.length?rev:others)[Number(day.replaceAll('-',''))%(rev.length||others.length)];const practice=Math.floor(minutes*.45),learning=Math.floor(minutes*.35);return [{topic:a.topic,kind:a.priority===0?'Weak-topic revision':a.priority===1?'Learn pending chapter':'Concept revision',minutes:learning,target:'Read notes and solve worked examples'},{topic:a.topic,kind:'Practice',minutes:practice,target:`Aim for ${Math.max(3,Math.floor(practice/2))} practice questions`},{topic:b.topic,kind:'Recall and review',minutes:minutes-learning-practice,target:'Recall formulas and review mistakes'}];
}
function practiceState(){try{return JSON.parse(localStorage.getItem('practice:v1:'+user.id)||'{}')||{}}catch{return {}}}
function practiceStats(state,topic,day){const rows=Object.values(state).filter(r=>r&&(!topic||r.topic===topic));const entries=rows.flatMap(r=>Object.entries(r.days||{}).filter(([d])=>!day||d===day).map(([,v])=>v));return {count:entries.length,correct:entries.filter(v=>v===true).length}}
async function advancedPractice(initial=1){
 const owner=user.id;let state=practiceState(),topic=initial,mode='all',qs=[],index=0,answered=false,loading=false;
 let statResult=await db.rpc('mission_topic_analytics_v1');if(user?.id!==owner)return;
 const weak=topics.map((_,i)=>{const p=practiceStats(state,i+1);const t=(statResult.data||[]).find(r=>Number(r.topic)===i+1);const n=p.count+Number(t?.correct||0)+Number(t?.wrong||0),c=p.correct+Number(t?.correct||0);return {topic:i+1,n,acc:n?c/n:1}}).filter(r=>r.n>=5&&r.acc<.6).sort((a,b)=>a.acc-b.acc);
 shell(`<h1>Advanced practice / उन्नत अभ्यास</h1><section class="panel"><div id="prstats"></div><label>Chapter<select id="prtopic">${topics.map((t,i)=>`<option value="${i+1}" ${i+1===topic?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Mode<select id="prmode"><option value="all">All questions</option><option value="fresh">Not attempted today</option><option value="mistakes">Unresolved mistakes</option></select></label><label>Difficulty / कठिनाई<select id="prdifficulty"><option value="all">All levels</option><option value="easy">Easy</option><option value="medium">Medium</option><option value="advanced">Direct Advanced (practice)</option><option value="unclassified">Original bank (unclassified)</option></select></label><button id="prstart">Start / restart</button>${weak.length?`<button id="prweak">Practice weakest topic: ${esc(topics[weak[0].topic-1])}</button>`:'<p>Weak-topic recommendations need at least 5 answers and below 60% accuracy.</p>'}<p><small>Practice history stays in this browser, separately for each account. Daily accuracy uses first answers only; retries can resolve mistakes. 42 original supplementary questions have estimated difficulty labels. Existing bank remains unclassified. Direct Advanced is a practice label, not official exam calibration.</small></p></section><section class="panel" id="prquestion"></section>`);
 const active=()=>user?.id===owner&&!!el('prquestion');
 function stats(){const d=practiceStats(state,0,plannerDay()),all=practiceStats(state,0);el('prstats').innerHTML=`<div class="grid"><article><h3>${d.count}</h3>Unique questions today</article><article><h3>${d.count?Math.round(100*d.correct/d.count)+'%':'—'}</h3>Today accuracy</article><article><h3>${all.count?Math.round(100*all.correct/all.count)+'%':'—'}</h3>Overall daily-first accuracy</article><article><h3>${Object.values(state).filter(r=>r.wrong).length}</h3>Unresolved mistakes</article></div>`}
 function draw(){if(!active())return;stats();answered=false;const q=qs[index];el('prquestion').innerHTML=q?`<small>Question ${index+1}/${qs.length} · ${esc(q.difficulty||"Unclassified")}</small><h3>${esc(q.prompt)}</h3>${q.options.map((o,j)=>`<button data-pick="${j}">${esc(o)}</button>`).join('')}<p id="prfeedback" aria-live="polite"></p><button id="prnext">Skip / next</button>`:'<p>Session complete or no matching questions. Select a mode and start again.</p>';if(!q)return;el('prquestion').querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{if(answered||!active())return;const correct=Number(b.dataset.pick)===Number(q.answer);const key=String(q.id),day=plannerDay();state=practiceState();const r=state[key]||{topic,days:{}};r.days=r.days||{};if(!(day in r.days))r.days[day]=correct;r.wrong=!correct;state[key]=r;try{localStorage.setItem('practice:v1:'+owner,JSON.stringify(state))}catch(e){alert('Practice could not be saved: '+e.message);return}answered=true;el('prquestion').querySelectorAll('[data-pick]').forEach(x=>{x.disabled=true});el('prfeedback').textContent=(correct?'Correct / सही: ':'Incorrect / गलत. Correct answer: '+q.options[q.answer]+' — ')+(q.explanation||'');stats()});bind('prnext',()=>{index++;draw()})}
 async function start(){if(loading)return;loading=true;const node=el('prquestion');topic=Number(val('prtopic'));mode=val('prmode');node.textContent='Loading practice…';try{const difficulty=val('prdifficulty');const original=await req(db.rpc('practice',{k:topic}));const rows=[...original,...difficultyBank2027.filter(q=>q.topic===topic)].filter(q=>difficulty==='all'||(q.difficulty||'unclassified')===difficulty);if(!active()||el('prquestion')!==node)return;state=practiceState();qs=rows.filter(q=>mode==='all'||(mode==='fresh'?!(plannerDay() in (state[q.id]?.days||{})):state[q.id]?.wrong));for(let i=qs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[qs[i],qs[j]]=[qs[j],qs[i]]}index=0;draw()}catch(e){if(active()&&el('prquestion')===node)node.textContent=e.message}finally{loading=false}}
 bind('prstart',start);if(el('prweak'))bind('prweak',()=>{el('prtopic').value=weak[0].topic;el('prmode').value='all';el('prdifficulty').value='all';return start()});await start();
}
function plannerDay(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function smartPlanner(progress,stats,available){
 const key='smartplanner:v1:'+user.id,day=plannerDay();let state={};try{state=JSON.parse(localStorage.getItem(key)||'{}')||{}}catch(e){};const options=[30,45,60,90,120,150,180];let minutes=options.includes(state.minutes)?state.minutes:60;let tasks=state.day===day&&Array.isArray(state.tasks)&&state.tasks.length===3&&state.tasks.every(t=>Number.isInteger(t.topic)&&t.topic>=1&&t.topic<=topics.length)?state.tasks:plannerTasks(progress,stats,minutes,day);let checked=state.day===day&&Array.isArray(state.checked)?state.checked.filter(i=>Number.isInteger(i)&&i>=0&&i<3):[];
 const save=()=>localStorage.setItem(key,JSON.stringify({day,minutes,tasks,checked}));const draw=()=>{el('smarttasks').innerHTML=tasks.map((t,i)=>`<article><label><input type="checkbox" data-task="${i}" ${checked.includes(i)?'checked':''}> ${esc(t.kind)} · ${esc(t.minutes)} min</label><h3>${esc(topics[t.topic-1])}</h3><p>${esc(t.target)}</p>${t.kind==='Practice'?`<p>Today: ${practiceStats(practiceState(),t.topic,day).count}/${Math.max(3,Math.floor(t.minutes/2))} unique questions</p><button onclick="run(()=>advancedPractice(${t.topic}))()">Start tracked practice</button>`:`<button onclick="run(()=>chapter(${t.topic}))()">Open chapter</button>`}</article>`).join('');el('smartcount').textContent=`${checked.length}/3 tasks completed`;el('smartbar').value=checked.length;el('smarttasks').querySelectorAll('[data-task]').forEach(x=>x.onchange=()=>{const i=Number(x.dataset.task);checked=x.checked?[...new Set([...checked,i])]:checked.filter(j=>j!==i);save();draw()})};
 el('smartminutes').innerHTML=options.map(m=>`<option value="${m}" ${m===minutes?'selected':''}>${m} minutes</option>`).join('');el('smartstatus').textContent=available?'Uses eligible closed-test analytics and chapter progress.':'Analytics unavailable; using chapter progress only.';bind('smartgenerate',()=>{if(checked.length&&!confirm('Regenerate today’s plan and reset its task checkmarks?'))return;minutes=Number(val('smartminutes'));tasks=plannerTasks(progress,stats,minutes,day);checked=[];save();draw()});save();draw();
}

async function personal(){const [progress,statResult]=await Promise.all([req(db.from('progress').select('*').eq('student',user.id)),db.rpc('mission_topic_analytics_v1')]);const items=await req(db.from('study_items').select('*').eq('student',user.id));const plan=await req(db.from('study_plans').select('body').eq('student',user.id).maybeSingle());shell(`<h1>My study space / अध्ययन</h1><section class="panel"><h2>Smart daily planner / दैनिक लक्ष्य</h2><p id="smartstatus"></p><label>Daily study time <select id="smartminutes"></select></label><button id="smartgenerate">Generate / update today’s plan</button><p id="smartcount"></p><progress id="smartbar" max="3" value="0"></progress><div id="smarttasks" class="grid"></div><small>Daily tasks and time preference saved on this browser only. Practice counts update when this page is opened; task checkmarks remain manual.</small></section><section class="panel"><h2>Daily planner</h2><textarea id="cloudplan">${esc(plan?.body||'')}</textarea><button id="savecloud">Save across devices</button></section>${['bookmark','mistake'].map(kind=>`<section class="panel"><h2>${kind==='bookmark'?'Bookmarks':'Mistake notebook'}</h2>${items.filter(i=>i.kind===kind).map(i=>`<p>${esc(topics[i.topic-1])} <button onclick="run(()=>chapter(${i.topic}))()">Review</button><button onclick="run(()=>removeItem(${i.topic},'${kind}'))()">Remove</button></p>`).join('')||'Nothing saved yet'}</section>`).join('')}`);smartPlanner(progress,statResult.data||[],!statResult.error);bind('savecloud',async()=>{await req(db.from('study_plans').upsert({student:user.id,body:val('cloudplan')}));alert('Saved')})}
async function removeItem(topic,kind){await req(db.from('study_items').delete().eq('student',user.id).eq('topic',topic).eq('kind',kind));await personal()}
async function announcements(){const rows=await req(db.from('resources').select('*').eq('kind','announcement').order('id',{ascending:false}));shell('<h1>Announcements / सूचना</h1>'+rows.map(r=>`<article><h3>${esc(r.title)}</h3><pre>${esc(r.body)}</pre></article>`).join(''))}

if(!cfg.url||!cfg.key){show('<h1>SUPER 100 · Mission 2027</h1><p>Setup required: configure Supabase in config.js. This is not a live login yet.</p><div class="grid">'+topics.map(t=>`<article>${esc(t)}</article>`).join('')+'</div>')}else{db=supabase.createClient(cfg.url,cfg.key);bind('logout',async()=>{await db.auth.signOut();load()});run(load)()}
